tem['tracking'] && $item['tracking']['fecha_limite']): ?><span>Límite: <?= format_date($item['tracking']['fecha_limite']) ?></span><?php endif; ?><?php if ($item['tracking'] && $item['tracking']['responsable']): ?><span><?= e($item['tracking']['responsable']) ?></span><?php endif; ?></div></div><?= icon('arrow-right', 'h-4 w-4 shrink-0 text-slate-300') ?></div></a><?php endforeach; ?></div></section><?php endforeach; ?></div>
