<form method="post" action="<?= e(url('/cumplimiento-documental/seguimiento')) ?>" class="ios-card p-5"><?= csrf_field() ?><input type="hidden" name="requisito_clave" value="<?= e($selected['key']) ?>"><h2 class="text-sm font-semibold">Seguimiento de la empresa</h2><label class="label mt-4">Estado</label><select name="estado" class="input"><?php foreach ($statusLabels as $state => $label): ?><option value="<?= e($state) ?>"<?= selected(old('estado', $selected['estado']), $state) ?>><?= e($label) ?></option><?php endforeach; ?></select><?= field_error('estado') ?><label class="label mt-3">Responsable</label><input name="responsable" class="input" value="<?= e(old('responsable', $selected['tracking']['responsable'] ?? $user['nombre'])) ?>"><?= field_error('responsable') ?><label class="label mt-3">Fecha límite</label><input name="fecha_limite" type="date" class="input" value="<?= e(old('fecha_limite', $selected['tracking']['fecha_limite'] ?? '')) ?>"><?= field_error('fecha_limite') ?><label class="label mt-3">Observaciones / alcance de la revisión</label><textarea name="observaciones" class="input min-h-28" placeholder="Qué se revisó, dónde está el soporte, alcance, limitaciones o justificación de no aplicabilidad"><?= e(old('observaciones', $selected['tracking']['observaciones'] ?? '')) ?></textarea><?= field_error('observaciones') ?><p class="mt-2 text-[10px] leading-4 text-slate-400">Para Verificado o No aplica, responsable y observaciones son obligatorios.</p><button class="btn-primary mt-4 w-full" type="submit">Guardar seguimiento</button></form>
