 text-slate-400">SHA-256: <?= e($support['hash_sha256']) ?></p><div class="mt-3 flex items-center justify-between"><a href="<?= e(url('/cumplimiento-documental/soportes/' . $support['id'] . '/descargar')) ?>" class="text-link text-[11px]">Descargar</a><form method="post" action="<?= e(url('/cumplimiento-documental/soportes/' . $support['id'] . '/eliminar')) ?>" data-confirm="¿Eliminar este soporte y su archivo físico?"><?= csrf_field() ?><button type="submit" class="text-[11px] font-medium text-rose-600">Eliminar</button></form></div></article><?php endforeach; ?></div></section>
